"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[23254],{79684(e,t,o){o.r(t),o.d(t,{assets:()=>u,contentTitle:()=>i,default:()=>d,frontMatter:()=>n,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"general/introducing-jumpcloud-reports-1234","title":"Introducing Jumpcloud Reports","description":"By dwjohn","source":"@site/docs/general/introducing-jumpcloud-reports-1234.md","sourceDirName":"general","slug":"/general/introducing-jumpcloud-reports-1234","permalink":"/jc-community-archive/general/introducing-jumpcloud-reports-1234","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Introducing Jumpcloud Reports","description":"By dwjohn"},"sidebar":"docs","previous":{"title":"Introducing Jumpcloud Mobile Device Trust","permalink":"/jc-community-archive/general/introducing-jumpcloud-mobile-device-trust"},"next":{"title":"Introducing Jumpcloud Reports","permalink":"/jc-community-archive/general/introducing-jumpcloud-reports"}}');var s=o(74848),a=o(28453);const n={title:"Introducing Jumpcloud Reports",description:"By dwjohn"},i=void 0,u={},l=[];function c(e){const t={a:"a",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"Hey JumpCloud Community! My name is Derek Johnson and I am a Principal Product Manager on the Data Services team at JumpCloud. This is my first community post and I am excited to provide more details about our new JumpCloud Reports feature and what we are working on for the future."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Background:"})," Our main goal on the JumpCloud Data Services team is to augment and enhance the value we provide to our customers through easy, frictionless access to JumpCloud Data. Given the various solutions offered in the JumpCloud Platform, we know that we are capturing a tremendous amount of data that if aggregated into certain views would provide significant value to our customers. In many cases, these aggregated views are already being created by some customers via automation and spreadsheets. JumpCloud Reports was designed to make it easier to retrieve some of these most common aggregations in pre-defined reports with near real-time data."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Tasks to be done:"})," When we created JumpCloud Reports, we knew that IT Administrators could use it for many tasks. The things we had in mind were helping to meet compliance requirements, assessing policy compliance, troubleshooting issues, and evaluating security posture to name a few. We also know that our customers are very creative in their use of this data. During the early stages of JumpCloud Reports, we heard from customers that were taking the report data and integrating it with other automation to provide even more value to themselves. We would love to hear creative ways that the community uses this data."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"General Reports Solution:"})," Administrators on the JumpCloud platform now have access to a \u201cReports\u201d tab under the \u201cInsights\u201d section on the left navigation in the Admin Console. This is the new home for JumpCloud Reports.\xa0 On this page, there is a dropdown selector that allows administrators to select the pre-defined report to be run, see an example of what data is in the report, and request that the report be executed. We will also make all of these capabilities available via api very soon."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Stored Report Queue:"})," One of the features that we felt was critical to launching a reporting feature was our Stored Reports Queue. We know that some reports will take some time to complete. We also know that customers may want to download a report more than once. Our Stored Report Queue gives administrators the ability to have a logical place to retrieve those longer running reports for download. Currently, we are keeping the last 10 reports for up to 7 days.\xa0 Once 7 days have passed for a report, it will fall out of the Stored Reports Queue.\xa0 Likewise, if there are 10 reports in the Stored Report Queue already and a new one is generated, the oldest report will fall out of the queue. All of the reports can be downloaded from the Stored Report Queue in either csv or json format."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Initial Reports:"})," Our initial focus for JumpCloud Reports was User to Resource associations. Basically answering the question - \u201cWho has access to what?\u201d These reports create tools and artifacts that can be used for so many purposes. Administrators now have something that they can show or give to stakeholders proving \u201cWho has access to what\u201d. The initial list includes:"]}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Users to Devices - Returns all user attributes and device associations for each user"}),"\n",(0,s.jsx)(t.li,{children:"Users to Directories - Returns all user attributes and associations to directories for each user"}),"\n",(0,s.jsx)(t.li,{children:"Users to LDAP - Returns all user attributes and associations to LDAP resources for each user"}),"\n",(0,s.jsx)(t.li,{children:"Users to RADIUS Server - Returns all user attributes and associations to RADIUS Servers for each user"}),"\n"]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Future Reports:"})," We are actively working on 2 additional reports to be released soon. We will do a separate community post once these reports are released."]}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Users to SSO Applications - Returns all user attributes and SSO application associations. This will include the last login timestamp to the application."}),"\n",(0,s.jsx)(t.li,{children:"OS Patch Management Policy Status - Returns all devices where an OS Patch Policy has been applied along with the current patch status and status message."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"We also have additional plans to add even more capabilities around JumpCloud Reports. Keep a lookout for report filtering, report scheduling, and report notifications to name a few."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Wrap Up:"})," If you are looking for more information on JumpCloud Reports, check out our ",(0,s.jsx)(t.a,{href:"https://support.jumpcloud.com/s/article/JumpCloud-Reports",children:"JumpCloud Reports"})," knowledge base article and ",(0,s.jsx)(t.a,{href:"https://jumpcloud.com/blog/jumpcloud-reports-data-benefits",children:"Introducing JumpCloud Reports: It\u2019s More Than Just Data"})," blog post. Give JumpCloud Reports a try and please share any stories that you have on how you used them or how they could be improved."]})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,t,o){o.d(t,{R:()=>n,x:()=>i});var r=o(96540);const s={},a=r.createContext(s);function n(e){const t=r.useContext(a);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:n(e.components),r.createElement(a.Provider,{value:t},e.children)}}}]);